sys_script_include.script:
var FilterAvailableManagers = Class.create();
FilterAvailableManagers.prototype = {
    initialize: function() {},

    getAvailableManagers: function() {
        var availableManagers = [];
        var managersInBases = new Set(); // Armazena os sys_ids de gerentes já cadastrados

        // Buscar todos os usuários que já são gerentes de alguma base
        var baseGR = new GlideRecord('x_1546361_bases_bases');
        baseGR.addNotNullQuery('assigned_to'); // Apenas registros onde há um gerente atribuído
        baseGR.query();

        while (baseGR.next()) {
            managersInBases.add(baseGR.assigned_to.toString()); // Adiciona os IDs ao Set
        }

        // Buscar usuários do sys_user que NÃO estão na lista de gerentes já cadastrados
        var userGR = new GlideRecord('sys_user');
        userGR.query();

        while (userGR.next()) {
            var userId = userGR.sys_id.toString();
            if (!managersInBases.has(userId)) { // Se o ID do usuário NÃO estiver na lista de gerentes, adiciona
                availableManagers.push(userId);
            }
        }

        return availableManagers.join(',');
    },

    type: 'FilterAvailableManagers'
};
